package com.group3.cityroad.entity;

import com.group3.cityroad.enums.PriorityEnum;
import com.group3.cityroad.enums.StatusEnum;
import jakarta.persistence.*;
import java.time.LocalDate;

/**
 * RepairSchedule — generated by SchedulingService after assessment.
 * Belongs to one RepairRequest. Tracks start/end dates and current status.
 */
@Entity
@Table(name = "repair_schedule")
public class RepairSchedule {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long scheduleId;

    @Column(nullable = false)
    private String requestId;        // denormalized for quick lookup

    @Column
    private String supervisorId;

    @Column
    private LocalDate startDate;

    @Column
    private LocalDate endDate;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private PriorityEnum priority;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private StatusEnum scheduleStatus;

    @Column
    private Boolean isDeferred;

    // --- Relationships ---

    @OneToOne(fetch = FetchType.EAGER)
    @JoinColumn(name = "repair_request_id", nullable = false)
    private RepairRequest repairRequest;

    // --- Constructors ---

    public RepairSchedule() {}

    public RepairSchedule(RepairRequest repairRequest, PriorityEnum priority,
                          LocalDate startDate, LocalDate endDate) {
        this.repairRequest = repairRequest;
        this.requestId = String.valueOf(repairRequest.getRequestId());
        this.priority = priority;
        this.startDate = startDate;
        this.endDate = endDate;
        this.scheduleStatus = StatusEnum.SCHEDULED;
        this.isDeferred = false;
    }

    // --- Methods (signatures from class diagram) ---

    public void generate() {
        throw new UnsupportedOperationException("Not yet implemented");
    }

    public void applyPriority() {
        throw new UnsupportedOperationException("Not yet implemented");
    }

    public void resolveConflicts() {
        throw new UnsupportedOperationException("Not yet implemented");
    }

    public void reschedule() {
        throw new UnsupportedOperationException("Not yet implemented");
    }

    // --- Getters and Setters ---

    public Long getScheduleId() { return scheduleId; }

    public String getRequestId() { return requestId; }
    public void setRequestId(String requestId) { this.requestId = requestId; }

    public String getSupervisorId() { return supervisorId; }
    public void setSupervisorId(String supervisorId) { this.supervisorId = supervisorId; }

    public LocalDate getStartDate() { return startDate; }
    public void setStartDate(LocalDate startDate) { this.startDate = startDate; }

    public LocalDate getEndDate() { return endDate; }
    public void setEndDate(LocalDate endDate) { this.endDate = endDate; }

    public PriorityEnum getPriority() { return priority; }
    public void setPriority(PriorityEnum priority) { this.priority = priority; }

    public StatusEnum getScheduleStatus() { return scheduleStatus; }
    public void setScheduleStatus(StatusEnum scheduleStatus) {
        this.scheduleStatus = scheduleStatus;
    }

    public Boolean getIsDeferred() { return isDeferred; }
    public void setIsDeferred(Boolean isDeferred) { this.isDeferred = isDeferred; }

    public RepairRequest getRepairRequest() { return repairRequest; }
    public void setRepairRequest(RepairRequest repairRequest) {
        this.repairRequest = repairRequest;
    }
}